    pub open spec fn update(self, v: V, mult: nat) -> Self {
        let map = Map::new(
            self.dom().insert(v),
            |key: V|
                if key == v {
                    mult
                } else {
                    self.count(key)
                },
        );
        Self::from_map(map)
    }

