    // invariant that the present axiom-heavy representation promises to maintain.
    pub broadcast proof fn dom_ensures(self)
        ensures
            #![trigger(self.dom())]
            forall|v: V| #[trigger]
                self.dom().contains(v) <==> self.count(v) > 0,
    {
